namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public int DepartmentId { get; set; }
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public string Schedule { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    public string Name { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }

    public DateTime SubmittedAt { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science" },
            new() { Id = 2, Name = "Mathematics" },
            new() { Id = 3, Name = "Physics" },
            new() { Id = 4, Name = "English" }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Code = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using C#. This course covers variables, control flow, and basic data structures. Ideal for beginners with no prior experience.", Credits = 3, DepartmentId = 1, InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education.", Schedule = "MWF 9:00-9:50 AM", IsFeatured = true },
            new() { Id = 2, Code = "CS201", Title = "Data Structures and Algorithms", Description = "A deep dive into fundamental data structures including trees, graphs, and hash tables. Students will implement and analyze algorithms for sorting, searching, and graph traversal.", Credits = 4, DepartmentId = 1, InstructorName = "Dr. Alice Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education.", Schedule = "TTh 10:30-11:45 AM", IsFeatured = false },
            new() { Id = 3, Code = "CS301", Title = "Database Systems", Description = "Study relational database design, SQL, and modern NoSQL systems. Covers normalization, indexing, query optimization, and transaction management.", Credits = 3, DepartmentId = 1, InstructorName = "Prof. Robert Kim", InstructorBio = "Prof. Kim worked at major tech companies for a decade before joining academia.", Schedule = "MWF 1:00-1:50 PM", IsFeatured = false },

            // Mathematics
            new() { Id = 4, Code = "MATH101", Title = "Calculus I", Description = "An introduction to differential calculus covering limits, derivatives, and applications. Students will develop problem-solving skills applicable across STEM fields.", Credits = 4, DepartmentId = 2, InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez is a published researcher in applied mathematics with a passion for teaching.", Schedule = "MWF 10:00-10:50 AM", IsFeatured = true },
            new() { Id = 5, Code = "MATH201", Title = "Linear Algebra", Description = "Explore vector spaces, matrices, eigenvalues, and linear transformations. This course builds the mathematical foundation for machine learning and computer graphics.", Credits = 3, DepartmentId = 2, InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez is a published researcher in applied mathematics with a passion for teaching.", Schedule = "TTh 9:00-10:15 AM", IsFeatured = false },
            new() { Id = 6, Code = "MATH301", Title = "Probability and Statistics", Description = "Study probability theory, random variables, and statistical inference. Applications include data analysis, hypothesis testing, and predictive modeling.", Credits = 3, DepartmentId = 2, InstructorName = "Dr. James Park", InstructorBio = "Dr. Park specializes in statistical modeling and has consulted for Fortune 500 companies.", Schedule = "MWF 2:00-2:50 PM", IsFeatured = false },

            // Physics
            new() { Id = 7, Code = "PHYS101", Title = "General Physics I", Description = "Covers classical mechanics including kinematics, Newton's laws, energy, and momentum. Laboratory sessions reinforce theoretical concepts with hands-on experiments.", Credits = 4, DepartmentId = 3, InstructorName = "Dr. Sarah Miller", InstructorBio = "Dr. Miller is an experimental physicist who has published over 50 research papers.", Schedule = "MWF 11:00-11:50 AM", IsFeatured = true },
            new() { Id = 8, Code = "PHYS201", Title = "Electromagnetism", Description = "Explore electric and magnetic fields, Maxwell's equations, and electromagnetic waves. This course bridges classical physics with modern applications in electronics.", Credits = 4, DepartmentId = 3, InstructorName = "Dr. Sarah Miller", InstructorBio = "Dr. Miller is an experimental physicist who has published over 50 research papers.", Schedule = "TTh 1:00-2:15 PM", IsFeatured = false },
            new() { Id = 9, Code = "PHYS301", Title = "Quantum Mechanics", Description = "An introduction to quantum theory covering wave functions, the Schrödinger equation, and quantum states. Explores the strange world of subatomic particles.", Credits = 3, DepartmentId = 3, InstructorName = "Prof. David Zhang", InstructorBio = "Prof. Zhang is a theoretical physicist specializing in quantum computing research.", Schedule = "MWF 3:00-3:50 PM", IsFeatured = false },

            // English
            new() { Id = 10, Code = "ENG101", Title = "Composition and Rhetoric", Description = "Develop essential writing skills including argumentation, research methods, and rhetorical analysis. Students produce multiple essays across various genres.", Credits = 3, DepartmentId = 4, InstructorName = "Prof. Emily Davis", InstructorBio = "Prof. Davis is an award-winning author and writing instructor with 20 years of teaching experience.", Schedule = "MWF 9:00-9:50 AM", IsFeatured = true },
            new() { Id = 11, Code = "ENG201", Title = "American Literature", Description = "Survey major works of American literature from the colonial period to the present. Examines themes of identity, freedom, and the American experience.", Credits = 3, DepartmentId = 4, InstructorName = "Prof. Emily Davis", InstructorBio = "Prof. Davis is an award-winning author and writing instructor with 20 years of teaching experience.", Schedule = "TTh 2:30-3:45 PM", IsFeatured = false },
            new() { Id = 12, Code = "ENG301", Title = "Creative Writing", Description = "Workshop-based course focusing on fiction and poetry. Students write, revise, and critique original works while studying craft elements from published authors.", Credits = 3, DepartmentId = 4, InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres has published three novels and numerous short stories in literary magazines.", Schedule = "TTh 10:30-11:45 AM", IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public List<Course> GetCourses(string? search, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        request.SubmittedAt = DateTime.UtcNow;
        _enrollments.Add(request);
    }

    public string? GetDepartmentName(int departmentId) =>
        _departments.FirstOrDefault(d => d.Id == departmentId)?.Name;
}

