@page "/enroll"
@inject CatalogService Catalog

<PageTitle>Enroll - University Course Catalog</PageTitle>

<h1 class="mb-4">Course Enrollment</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Enrollment Submitted!</h4>
        <p>Thank you, <strong>@Model.Name</strong>. Your enrollment request for the selected course has been received.</p>
        <hr />
        <p class="mb-0">Student ID: @Model.StudentId | Submitted at: @Model.SubmittedAt.ToString("f")</p>
    </div>
    <a href="/courses" class="btn btn-primary">Browse More Courses</a>
}
else
{
    <div class="row">
        <div class="col-lg-6">
            <form method="post">
                <AntiforgeryToken />

                @if (validationErrors.Any())
                {
                    <div class="alert alert-danger">
                        <ul class="mb-0">
                            @foreach (var error in validationErrors)
                            {
                                <li>@error</li>
                            }
                        </ul>
                    </div>
                }

                <div class="mb-3">
                    <label for="name" class="form-label">Full Name</label>
                    <input type="text" id="name" name="Model.Name" class="form-control" value="@Model.Name" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" id="studentId" name="Model.StudentId" class="form-control" value="@Model.StudentId" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <select id="courseId" name="Model.CourseId" class="form-select">
                        <option value="0">-- Select a Course --</option>
                        @foreach (var course in courses)
                        {
                            <option value="@course.Id" selected="@(Model.CourseId == course.Id)">@course.Code - @course.Title</option>
                        }
                    </select>
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment</button>
            </form>
        </div>
    </div>
}

